package com.spai.portal.asset.controller;
import java.io.*;import java.net.URLEncoder;import com.spai.portal.asset.domain.FileObject;import com.spai.portal.asset.service.FileStorageService;import com.spai.portal.common.ApiResponse;import org.springframework.http.*;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.web.bind.annotation.*;import org.springframework.web.multipart.MultipartFile;
@RestController @RequestMapping("/api/v1/files") public class FileController {private final FileStorageService service;private final java.util.List<com.spai.portal.asset.service.FileReadPolicy> policies;public FileController(FileStorageService service,java.util.List<com.spai.portal.asset.service.FileReadPolicy> policies){this.service=service;this.policies=policies;}@PostMapping("/upload")public ApiResponse<FileObject>upload(@RequestParam("file")MultipartFile file){return ApiResponse.ok(service.store(file));}@GetMapping("/{id}/preview")public ResponseEntity<org.springframework.core.io.Resource>preview(@PathVariable String id)throws IOException{return response(id,false);}@GetMapping("/{id}/download")public ResponseEntity<org.springframework.core.io.Resource>download(@PathVariable String id)throws IOException{return response(id,true);}private ResponseEntity<org.springframework.core.io.Resource>response(String id,boolean download)throws IOException{for(com.spai.portal.asset.service.FileReadPolicy policy:policies)policy.checkRead(id);FileStorageService.StoredFile f=service.load(id);String encoded=URLEncoder.encode(f.metadata.getFileName(),"UTF-8").replace("+","%20");return ResponseEntity.ok().contentType(MediaType.parseMediaType(f.metadata.getContentType()==null?"application/octet-stream":f.metadata.getContentType())).contentLength(f.metadata.getFileSize()).header(HttpHeaders.CONTENT_DISPOSITION,(download?"attachment":"inline")+"; filename*=UTF-8''"+encoded).cacheControl(CacheControl.noStore()).body(f.resource);}}
